		console.log(`  push:          ${envelope.push ? `only to ${envelope.remote}/${envelope.branch} (no force, no tags, no deletes)` : "none"}`);
		console.log(`  keep going:    ${session ? `${session.host || "agent"} session ${session.sessionId} (last active ${ago(session.lastSeenAt)})` : flags.noKeepGoing || !envelope.keepGoing ? "off" : "off: no agent session was active near the plan in the last 30 min (pass --session <heli-session-id>)"}`);
		console.log("  still blocked: other branches and main, force pushes, tags, publish/release/deploy approvals, .env writes, T6 commands, Heli's own state and the project's governance files");
